/**
 * Why the vault cannot be read. Each case is one thing the extension says.
 */
public 
enum AutofillError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * No vault in the container: Rowel was never set up on this device, or
     * its data is still in the app's own sandbox (an App Group the build was
     * not entitled to).
     */
    case NoVault
    /**
     * Nothing here is unlockable without the master password: Face ID unlock
     * is off, or the active workspace has no key sealed under the app key.
     */
    case Locked
    /**
     * The key read from the keychain does not open the vault.
     */
    case WrongKey
    /**
     * A master-password change was interrupted. The app rolls the vault back
     * at its next unlock; until then the database and the sealed payloads
     * may be on different keys, and nothing here writes but a passkey.
     */
    case Recovering
    /**
     * Nothing to fill under that record for that site: the login is gone,
     * another workspace's, moved to another site, or has no password. For a
     * passkey sign-in, no passkey for the site that the request admits (and
     * the record names, when it names one): iOS's `credentialIdentityNotFound`.
     */
    case NotFound
    /**
     * A passkey sign-in with several accounts to be and none picked: the
     * sheet lists them rather than asking with no record.
     */
    case Denied
    /**
     * The registration's exclude list names a passkey this vault holds: the
     * account already has one here, and a second is not made.
     */
    case Excluded
    /**
     * The relying party takes no ES256 key, the one kind the vault makes.
     */
    case Unsupported
    case Io(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AutofillError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAutofillError: FfiConverterRustBuffer {
    typealias SwiftType = AutofillError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AutofillError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NoVault
        case 2: return .Locked
        case 3: return .WrongKey
        case 4: return .Recovering
        case 5: return .NotFound
        case 6: return .Denied
        case 7: return .Excluded
        case 8: return .Unsupported
        case 9: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AutofillError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NoVault:
            writeInt(&buf, Int32(1))
        
        
        case .Locked:
            writeInt(&buf, Int32(2))
        
        
        case .WrongKey:
            writeInt(&buf, Int32(3))
        
        
        case .Recovering:
            writeInt(&buf, Int32(4))
        
        
        case .NotFound:
            writeInt(&buf, Int32(5))
        
        
        case .Denied:
            writeInt(&buf, Int32(6))
        
        
        case .Excluded:
            writeInt(&buf, Int32(7))
        
        
        case .Unsupported:
            writeInt(&buf, Int32(8))
        
        
        case let .Io(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


